def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the full stripe of 2s.
    stripe = None
    for r in range(h):
        if all(v == 2 for v in grid[r]):
            stripe = ("row", r)
            break
    if stripe is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                stripe = ("col", c)
                break

    # The most common non-stripe color is the background.
    counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != 2]
    if not cells or stripe is None:
        return out

    rmin = min(r for r, c in cells)
    rmax = max(r for r, c in cells)
    cmin = min(c for r, c in cells)
    cmax = max(c for r, c in cells)

    axis, pos = stripe
    if axis == "row":
        if rmin > pos:          # Object below stripe; move it up.
            dr = pos + 1 - rmin
            line = rmax + dr + 1
        else:                   # Object above stripe; move it down.
            dr = pos - 1 - rmax
            line = rmin + dr - 1
        dc = 0
    else:
        if cmin > pos:          # Object right of stripe; move it left.
            dc = pos + 1 - cmin
            line = cmax + dc + 1
        else:                   # Object left of stripe; move it right.
            dc = pos - 1 - cmax
            line = cmin + dc - 1
        dr = 0

    for r, c in cells:
        out[r][c] = bg
    for r, c in cells:
        out[r + dr][c + dc] = grid[r][c]

    if axis == "row" and 0 <= line < h:
        out[line] = [8] * w
    elif axis == "col" and 0 <= line < w:
        for r in range(h):
            out[r][line] = 8

    return out
